package io.github.wahindra.secure;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Properties;

/** Values from test-vectors/crypto-fixtures.properties, generated by the JavaScript implementation. */
final class CrossLanguage {

    static final String JS_HASH;
    static final String HMAC_OF_HELLO;
    /** HMAC-SHA256 hex of {"event":"paid"}, generated with openssl. */
    static final String HMAC_HEX_PAID;

    static {
        Properties p = new Properties();
        try (InputStream in = Files.newInputStream(
                Paths.get(System.getProperty("vectors.dir", "../../test-vectors"), "crypto-fixtures.properties"))) {
            p.load(in);
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
        JS_HASH = p.getProperty("password.hash");
        HMAC_OF_HELLO = p.getProperty("hmac.hello");
        HMAC_HEX_PAID = p.getProperty("hmac.hex.paid");
    }

    private CrossLanguage() {
    }
}
